using Microsoft.EntityFrameworkCore; using Movies.Database; using Movies.Domain;
namespace Movies.Services;
public sealed class MovieService(MoviesDbContext db) : IMovieService { public async Task<IReadOnlyList<MovieResponseDto>> GetActiveAsync(string? search, CancellationToken token) { var query=db.Movies.AsNoTracking().Where(x=>x.Status==MovieStatus.Active); if(!string.IsNullOrWhiteSpace(search)) query=query.Where(x=>x.Title.Contains(search)||x.Genre.Contains(search)); return await query.OrderBy(x=>x.Title).Select(x=>new MovieResponseDto { Id=x.Id,Title=x.Title,Description=x.Description,Genre=x.Genre,DurationMinutes=x.DurationMinutes,PremiereDate=x.PremiereDate,AgeRating=x.AgeRating,PosterBase64=x.PosterBase64,AverageRating=x.AverageRating,Status=x.Status }).ToListAsync(token); } }
